const b = $input.first().json.body || $input.first().json;

if (!b.siteId) throw new Error('Missing required field: siteId');
if (!b.message) throw new Error('Missing required field: message');
if (typeof b.message !== 'string' || b.message.trim().length === 0) {
  throw new Error('Message must be a non-empty string');
}

const msg = b.message.toLowerCase().trim();

const actionWords = /\b(implement|create|add|build|make|fix|update|change|edit|delete|remove|install|modify|replace|refactor|style|redesign|adjust|set|configure|enable|disable|connect|integrate|write|code)\b/;
const questionWords = /^(what|why|how|can you|could you|should|would|is it|are there|explain|describe|tell me|help me understand)/;
const isQuestion = questionWords.test(msg);
const hasActionWord = actionWords.test(msg);
const isActionIntent = hasActionWord && !isQuestion;
const isDebugRequest = /\b(bug|error|broken|not working|doesn't work|issue|problem|debug|fix|crash|undefined|null|failed)\b/.test(msg);

return [{
  json: {
    siteId: b.siteId,
    conversationId: b.conversationId || null,
    userId: b.userId || 'anon',
    message: b.message.trim(),
    requestId: 'req_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9),
    image: b.image || null,
    isActionIntent,
    isDebugRequest,
    isQuestion
  }
}];

const inp = $('Validate & Detect Intent').item.json;
const rawSite = $input.first().json;

let site = null;
if (Array.isArray(rawSite)) {
  site = rawSite[0];
} else if (rawSite && rawSite.id) {
  site = rawSite;
} else if (rawSite && Array.isArray(rawSite.data)) {
  site = rawSite.data[0];
}

if (!site || !site.id) {
  throw new Error(`Site not found for siteId: ${inp.siteId}`);
}

const repoMatch = (site.repo_url || '').match(/github\.com\/([^/]+)\/([^/]+)/);
if (!repoMatch) {
  throw new Error(`Invalid GitHub repo URL: ${site.repo_url}`);
}

const owner = repoMatch[1];
const repo = repoMatch[2].replace(/\.git$/, '');
const msg = inp.message.toLowerCase();

const fileScores = new Map();
const addFile = (file, score) => {
  fileScores.set(file, (fileScores.get(file) || 0) + score);
};

if (/shop|brand|name|title|logo/.test(msg)) {
  addFile('src/components/Header.tsx', 15);
  addFile('src/components/Navbar.tsx', 12);
  addFile('src/app/layout.tsx', 10);
  addFile('src/components/Footer.tsx', 8);
}

if (/color|theme|style|css|dark|light|design|palette|brand/.test(msg)) {
  addFile('src/app/globals.css', 10);
  addFile('src/index.css', 8);
  addFile('tailwind.config.ts', 7);
  addFile('tailwind.config.js', 5);
}

const componentPatterns = [
  { pattern: /header|nav|menu|navbar/, files: ['src/components/Header.tsx', 'src/components/Navbar.tsx'] },
  { pattern: /footer/, files: ['src/components/Footer.tsx'] },
  { pattern: /button/, files: ['src/components/ui/button.tsx'] },
  { pattern: /hero/, files: ['src/components/Hero.tsx', 'src/components/HeroSection.tsx'] },
];

for (const { pattern, files } of componentPatterns) {
  if (pattern.test(msg)) {
    files.forEach((f, i) => addFile(f, 8 - i));
  }
}

if (/layout|structure|wrapper/.test(msg)) {
  addFile('src/app/layout.tsx', 9);
}

if (/page|home|hero|landing|main|index/.test(msg) || fileScores.size === 0) {
  addFile('src/app/page.tsx', 10);
}

const sortedFiles = [...fileScores.entries()]
  .sort((a, b) => b[1] - a[1])
  .slice(0, 4)
  .map(([file]) => file);

if (sortedFiles.length === 0) {
  sortedFiles.push('src/app/page.tsx');
}

// Build preview URL
const previewUrl = `https://${site.id}.preview.automatelb.com`;

return [{
  json: {
    ...inp,
    site: {
      id: site.id,
      name: site.name || 'Unknown',
      repo_url: site.repo_url,
      branch: site.default_branch || 'main'
    },
    owner,
    repo,
    branch: site.default_branch || 'main',
    previewUrl,
    filesToFetch: sortedFiles,
    fileContents: {},
    contextFiles: []
  }
}];

const ctx = $('Build Context').item.json;
const files = ctx.filesToFetch || [];
if (files.length === 0) {
  return [{ json: { ...ctx, currentFile: null } }];
}

return files.map(f => ({
  json: {
    _ctx: {
      siteId: ctx.siteId,
      conversationId: ctx.conversationId,
      userId: ctx.userId,
      message: ctx.message,
      image: ctx.image,
      requestId: ctx.requestId,
      isActionIntent: ctx.isActionIntent,
      isDebugRequest: ctx.isDebugRequest,
      isQuestion: ctx.isQuestion,
      site: ctx.site,
      owner: ctx.owner,
      repo: ctx.repo,
      branch: ctx.branch,
      previewUrl: ctx.previewUrl,
      filesToFetch: files
    },
    currentFile: f,
    owner: ctx.owner,
    repo: ctx.repo,
    branch: ctx.branch
  }
}));

const items = $input.all();
const prepItems = $('Prepare Fetch').all();

let ctx = null;
if (prepItems.length > 0 && prepItems[0].json._ctx) {
  ctx = prepItems[0].json._ctx;
} else {
  throw new Error('Lost context during file fetch');
}

const fileContents = {};
const contextFiles = [];
const errors = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i].json;
  const filePath = prepItems[i]?.json?.currentFile;
  const githubPath = item.path;
  const path = filePath || githubPath;

  if (!path) {
    errors.push('Could not determine file path for item ' + i);
    continue;
  }

  const content = item.content;
  const errorMsg = item.message;

  if (content) {
    try {
      const decoded = Buffer.from(content, 'base64').toString('utf8');
      if (decoded.length > 4000) {
        fileContents[path] = decoded.substring(0, 4000) + '\n// ... truncated (' + decoded.length + ' chars total)';
      } else {
        fileContents[path] = decoded;
      }
      contextFiles.push(path);
    } catch (e) {
      errors.push(`Failed to decode ${path}: ${e.message}`);
    }
  } else if (errorMsg && !errorMsg.includes('Not Found')) {
    errors.push(`${path}: ${errorMsg}`);
  }
}

return [{
  json: {
    siteId: ctx.siteId,
    conversationId: ctx.conversationId,
    userId: ctx.userId,
    message: ctx.message,
    image: ctx.image,
    requestId: ctx.requestId,
    isActionIntent: ctx.isActionIntent,
    isDebugRequest: ctx.isDebugRequest,
    isQuestion: ctx.isQuestion,
    site: ctx.site,
    owner: ctx.owner,
    repo: ctx.repo,
    branch: ctx.branch,
    previewUrl: ctx.previewUrl,
    fileContents,
    contextFiles,
    loadErrors: errors
  }
}];

