// FIXED: Handle Claude's wrapped input format
let path = '.';
const rawInput = $fromAI('input', 'JSON input', 'string') || $fromAI('path', 'Directory path', 'string') || '';

if (rawInput) {
  try {
    const parsed = JSON.parse(rawInput);
    path = parsed.path || parsed.input || '.';
    // Handle double-wrapped JSON
    if (typeof path === 'string' && path.startsWith('{')) {
      const inner = JSON.parse(path);
      path = inner.path || '.';
    }
  } catch {
    path = rawInput.trim() || '.';
  }
}

const ctx = $('Merge Files')?.item?.json || {};
const { owner, repo, branch } = ctx;

if (!owner || !repo) return 'Error: No repository context';

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${owner}/${repo}/git/trees/${branch}?recursive=1`,
    headers: {
      'Authorization': 'Bearer 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',
      'Accept': 'application/vnd.github+json'
    },
    timeout: 15000
  });

  const normalizedPath = path.replace(/^\/+/, '').replace(/\/+$/, '');
  let files = (response.tree || []).filter(f => f.type === 'blob').map(f => f.path);

  if (normalizedPath && normalizedPath !== '.') {
    files = files.filter(f => f.startsWith(normalizedPath + '/'));
  }

  return files.slice(0, 50).join('\n') || 'No files found in ' + path;
} catch (e) {
  return 'Error: ' + e.message;
}

// FIXED: Handle Claude's wrapped input format
let filePath = '';
const rawInput = $fromAI('input', 'JSON input', 'string') || $fromAI('path', 'File path', 'string') || '';

if (rawInput) {
  try {
    const parsed = JSON.parse(rawInput);
    filePath = parsed.path || parsed.filePath || parsed.file_path || '';
    // Handle double-wrapped JSON
    if (typeof filePath === 'string' && filePath.startsWith('{')) {
      const inner = JSON.parse(filePath);
      filePath = inner.path || inner.filePath || '';
    }
  } catch {
    filePath = rawInput.trim();
  }
}

filePath = (filePath || '').trim().replace(/^\/+/, '');

if (!filePath) return 'Error: File path is required. Pass as JSON: {"path": "src/file.tsx"}';

const ctx = $('Merge Files')?.item?.json || {};

if (ctx.fileContents && ctx.fileContents[filePath]) {
  return 'This file is ALREADY in context above. Look at the FILES IN CONTEXT section.';
}

const { owner, repo, branch } = ctx;
if (!owner || !repo) return 'Error: No repository context';

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${encodeURIComponent(filePath)}?ref=${branch}`,
    headers: {
      'Authorization': 'Bearer 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',
      'Accept': 'application/vnd.github+json'
    },
    timeout: 15000
  });

  if (response.content) {
    const content = Buffer.from(response.content, 'base64').toString('utf8');
    return content.length > 6000 ? content.substring(0, 6000) + '\n// ... truncated' : content;
  }
  return 'Error: No content in response';
} catch (e) {
  return e.message.includes('404') ? 'Error: File not found: ' + filePath : 'Error: ' + e.message;
}

// FIXED: Handle Claude's wrapped input format
let filePath = '';
let content = '';

// Try to get direct parameters first
const rawFilePath = $fromAI('filePath', 'File path', 'string') || '';
const rawContent = $fromAI('content', 'File content', 'string') || '';
const rawInput = $fromAI('input', 'JSON input', 'string') || '';

// If we have direct params, use them
if (rawFilePath && rawContent) {
  filePath = rawFilePath;
  content = rawContent;
} else {
  // Parse from input field (Claude wraps params here)
  const toParse = rawInput || rawFilePath || rawContent;
  if (toParse) {
    try {
      let parsed = JSON.parse(toParse);
      // Handle double-wrapped JSON
      if (parsed.input && typeof parsed.input === 'string') {
        try { parsed = JSON.parse(parsed.input); } catch {}
      }
      filePath = parsed.filePath || parsed.file_path || parsed.path || '';
      content = parsed.content || '';
    } catch {
      // Try to extract from YAML-like format
      const fpMatch = toParse.match(/filePath[:\s]+["']?([^"'\n]+)/i);
      const ctMatch = toParse.match(/content[:\s]+["']([\s\S]*)["']$/i);
      if (fpMatch) filePath = fpMatch[1].trim();
      if (ctMatch) content = ctMatch[1];
    }
  }
}

filePath = (filePath || '').trim().replace(/^\/+/, '');

if (!filePath) return 'Error: filePath is required. Pass as JSON: {"filePath": "src/file.tsx", "content": "..."}';
if (!content && content !== '') return 'Error: content is required';

const ctx = $('Merge Files')?.item?.json || {};
const { owner, repo, branch } = ctx;
const siteId = ctx.site?.id || ctx.siteId;

if (!owner || !repo) return 'Error: No repository context';

try {
  // Update preview (fire and forget)
  if (siteId) {
    this.helpers.httpRequest({
      method: 'POST',
      url: 'https://preview-orchestrator.fly.dev/preview/write',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ siteId, filePath, content }),
      timeout: 5000
    }).catch(() => {});
  }

  // Check if file exists
  let sha = null;
  try {
    const existing = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://api.github.com/repos/${owner}/${repo}/contents/${encodeURIComponent(filePath)}?ref=${branch}`,
      headers: { 'Authorization': 'Bearer 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', 'Accept': 'application/vnd.github+json' },
      timeout: 10000
    });
    sha = existing.sha;
  } catch {}

  const body = { message: (sha ? 'Update ' : 'Create ') + filePath, content: Buffer.from(content).toString('base64'), branch };
  if (sha) body.sha = sha;

  await this.helpers.httpRequest({
    method: 'PUT',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${encodeURIComponent(filePath)}`,
    headers: { 'Authorization': 'Bearer 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', 'Accept': 'application/vnd.github+json', 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
    timeout: 30000
  });

  return JSON.stringify({ success: true, file: filePath, action: sha ? 'updated' : 'created' });
} catch (e) {
  return 'Error: ' + e.message;
}

// FIXED: Handle Claude's wrapped input format
let filePath = '';
let search = '';
let replace = '';

// Try direct parameters
const rawFilePath = $fromAI('filePath', 'File path', 'string') || '';
const rawSearch = $fromAI('search', 'Text to find', 'string') || '';
const rawReplace = $fromAI('replace', 'Replacement text', 'string') || '';
const rawInput = $fromAI('input', 'JSON input', 'string') || '';

// If we have all direct params, use them
if (rawFilePath && rawSearch !== undefined && rawSearch !== '') {
  filePath = rawFilePath;
  search = rawSearch;
  replace = rawReplace || '';
} else {
  // Parse from input field (Claude wraps params here)
  const toParse = rawInput || rawFilePath || rawSearch;
  if (toParse) {
    try {
      let parsed = JSON.parse(toParse);
      // Handle double-wrapped JSON  
      if (parsed.input && typeof parsed.input === 'string') {
        try { parsed = JSON.parse(parsed.input); } catch {}
      }
      filePath = parsed.filePath || parsed.file_path || parsed.path || '';
      search = parsed.search || '';
      replace = parsed.replace !== undefined ? parsed.replace : '';
    } catch {
      // Try YAML-like format
      const fpMatch = toParse.match(/filePath[:\s]+["']?([^"'\n]+)/i);
      const srMatch = toParse.match(/search[:\s]+["']([^"']+)["']/i);
      const rpMatch = toParse.match(/replace[:\s]+["']([^"']*)["']/i);
      if (fpMatch) filePath = fpMatch[1].trim();
      if (srMatch) search = srMatch[1];
      if (rpMatch) replace = rpMatch[1];
    }
  }
}

filePath = (filePath || '').trim().replace(/^\/+/, '');

if (!filePath) return 'Error: filePath is required. Pass as JSON: {"filePath": "src/file.tsx", "search": "old", "replace": "new"}';
if (!search) return 'Error: search text is required';

const ctx = $('Merge Files')?.item?.json || {};
const { owner, repo, branch } = ctx;
const siteId = ctx.site?.id || ctx.siteId;

if (!owner || !repo) return 'Error: No repository context';

try {
  // Get current file
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${encodeURIComponent(filePath)}?ref=${branch}`,
    headers: { 'Authorization': 'Bearer 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', 'Accept': 'application/vnd.github+json' },
    timeout: 15000
  });

  let content = Buffer.from(response.content, 'base64').toString('utf8');

  // Check if search text exists
  if (!content.includes(search)) {
    const searchStart = search.substring(0, 30).trim();
    const lines = content.split('\n');
    let hint = '';
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].toLowerCase().includes(searchStart.toLowerCase().substring(0, 15))) {
        hint = `Line ${i+1}: "${lines[i].trim().substring(0, 60)}..."`;
        break;
      }
    }
    return `Error: Search text not found. Text must match EXACTLY (case-sensitive).${hint ? ' Similar: ' + hint : ''}`;
  }

  // Replace
  content = content.replace(search, replace);

  // Update preview
  if (siteId) {
    this.helpers.httpRequest({
      method: 'POST',
      url: 'https://preview-orchestrator.fly.dev/preview/write',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ siteId, filePath, content }),
      timeout: 5000
    }).catch(() => {});
  }

  // Commit
  await this.helpers.httpRequest({
    method: 'PUT',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${encodeURIComponent(filePath)}`,
    headers: { 'Authorization': 'Bearer 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', 'Accept': 'application/vnd.github+json', 'Content-Type': 'application/json' },
    body: JSON.stringify({ message: 'Update ' + filePath, content: Buffer.from(content).toString('base64'), sha: response.sha, branch }),
    timeout: 30000
  });

  return JSON.stringify({ success: true, file: filePath, action: 'updated' });
} catch (e) {
  return e.message.includes('404') ? 'Error: File not found: ' + filePath : 'Error: ' + e.message;
}

let filePath = '';
const rawInput = $fromAI('input', 'JSON input', 'string') || $fromAI('path', 'File path', 'string') || '';

if (rawInput) {
  try {
    const parsed = JSON.parse(rawInput);
    filePath = parsed.path || parsed.filePath || '';
  } catch {
    filePath = rawInput.trim();
  }
}

filePath = (filePath || '').trim().replace(/^\/+/, '');

if (!filePath) return 'Error: File path is required';

const ctx = $('Merge Files')?.item?.json || {};
const { owner, repo, branch } = ctx;

if (!owner || !repo) return 'Error: No repository context';

try {
  const existing = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${encodeURIComponent(filePath)}?ref=${branch}`,
    headers: { 'Authorization': 'Bearer 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', 'Accept': 'application/vnd.github+json' },
    timeout: 10000
  });

  await this.helpers.httpRequest({
    method: 'DELETE',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${encodeURIComponent(filePath)}`,
    headers: { 'Authorization': 'Bearer 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', 'Accept': 'application/vnd.github+json', 'Content-Type': 'application/json' },
    body: JSON.stringify({ message: 'Delete ' + filePath, sha: existing.sha, branch }),
    timeout: 15000
  });

  return JSON.stringify({ success: true, deleted: filePath });
} catch (e) {
  return e.message.includes('404') ? 'Error: File not found: ' + filePath : 'Error: ' + e.message;
}

let query = '';
const rawInput = $fromAI('input', 'JSON input', 'string') || $fromAI('query', 'Search query', 'string') || '';

if (rawInput) {
  try {
    const parsed = JSON.parse(rawInput);
    query = parsed.query || parsed.input || '';
  } catch {
    query = rawInput.trim();
  }
}

query = (query || '').trim();

if (!query) return 'Error: Search query is required';
if (query.length < 3) return 'Error: Query too short. Use list_files instead.';

const ctx = $('Merge Files')?.item?.json || {};
const { owner, repo } = ctx;

if (!owner || !repo) return 'Error: No repository context';

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/search/code?q=${encodeURIComponent(query)}+repo:${owner}/${repo}`,
    headers: { 'Authorization': 'Bearer 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', 'Accept': 'application/vnd.github+json' },
    timeout: 20000
  });

  if (response.items && response.items.length > 0) {
    return 'Found in ' + response.total_count + ' file(s):\n' + response.items.slice(0, 15).map(i => i.path).join('\n');
  }
  return 'No results for: "' + query + '"';
} catch (e) {
  return e.message.includes('rate limit') ? 'Search rate limited. Use list_files instead.' : 'Error: ' + e.message;
}

let pkg = '';
const rawInput = $fromAI('input', 'JSON input', 'string') || $fromAI('package', 'Package name', 'string') || '';

if (rawInput) {
  try {
    const parsed = JSON.parse(rawInput);
    pkg = parsed.package || parsed.name || '';
  } catch {
    pkg = rawInput.trim();
  }
}

pkg = (pkg || '').trim();
if (!pkg) return 'Error: Package name is required';

const ctx = $('Merge Files')?.item?.json || {};
const siteId = ctx.site?.id || ctx.siteId;

if (!siteId) return 'Error: No site context';

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://preview-orchestrator.fly.dev/preview/install',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ siteId, packages: [pkg] }),
    timeout: 120000
  });
  return JSON.stringify({ success: true, installed: response.installed || [pkg] });
} catch (e) {
  return 'Error: ' + e.message;
}

const ctx = $('Merge Files').item.json;
const raw = $('AI Agent').item.json;

const output = raw?.output || '';
const steps = raw?.intermediateSteps || [];

const filesModified = new Set();
const filesCreated = new Set();
const filesDeleted = new Set();
const errors = [];
const toolCalls = [];

for (const step of steps) {
  if (step.action?.tool) {
    toolCalls.push(step.action.tool);
  }

  const obs = step.observation || '';

  try {
    const result = JSON.parse(obs);
    if (result.success) {
      const file = result.file || result.to;
      if (file) {
        if (result.action === 'created') filesCreated.add(file);
        else if (result.action === 'updated') filesModified.add(file);
      }
      if (result.deleted) filesDeleted.add(result.deleted);
    }
    if (result.error) errors.push(result.error);
  } catch {}
}

const warnings = [];
if (filesModified.size === 0 && filesCreated.size === 0 && filesDeleted.size === 0 && steps.length > 2) {
  warnings.push('No files were modified');
}
if (errors.length > 0) warnings.push(...errors.slice(0, 2));

return [{
  json: {
    ...ctx,
    plan: { humanSummary: output, warnings },
    filesModified: [...filesModified],
    filesCreated: [...filesCreated],
    filesDeleted: [...filesDeleted],
    iterations: steps.length,
    toolsUsed: [...new Set(toolCalls)]
  }
}];
